"use client";

import { useState } from "react";

type Props = {
  projectId: string;
};

export default function BuilderInner({ projectId }: Props) {
  const [filePath, setFilePath] = useState("");
  const [content, setContent] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    if (!filePath) return;

    try {
      setSaving(true);

      const res = await fetch("/api/dev/files/write", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          projectId,
          filePath,
          content,
        }),
      });

      const data = await res.json();

      if (!data.ok) {
        console.error("Save failed:", data.error);
        return;
      }

      // ONLY trigger AFTER successful save
      setRefreshKey((prev) => prev + 1);
    } catch (err) {
      console.error("Save error:", err);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* LEFT: editor */}
      <div style={{ width: "50%", padding: 16 }}>
        <input
          value={filePath}
          onChange={(e) => setFilePath(e.target.value)}
          placeholder="app/page.tsx"
          style={{
            width: "100%",
            marginBottom: 8,
            padding: 8,
            border: "1px solid #ccc",
          }}
        />

        <textarea
          value={content}
          onChange={(e) => setContent(e.target.value)}
          style={{
            width: "100%",
            height: "70%",
            padding: 12,
            border: "1px solid #ccc",
            fontFamily: "monospace",
          }}
        />

        <button
          onClick={handleSave}
          disabled={saving}
          style={{
            marginTop: 12,
            padding: "10px 16px",
            background: "black",
            color: "white",
            cursor: "pointer",
          }}
        >
          {saving ? "Saving..." : "Save"}
        </button>
      </div>

      {/* RIGHT: preview */}
      <div style={{ width: "50%", borderLeft: "1px solid #eee" }}>
        <iframe
          key={refreshKey}
          src={`/api/dev/preview?projectId=${projectId}&v=${refreshKey}`}
          style={{
            width: "100%",
            height: "100%",
            border: "none",
            background: "white",
          }}
        />
      </div>
    </div>
  );
}
EOF

